options.helpers:
const selSev = context.grafana.replaceVariables('${severity}');

context.handlebars.registerHelper('severityMatch', function(badge, options) {
  const cur = context.grafana.replaceVariables('${severity}');
  if (!cur || cur === 'All' || cur === '.*' || cur === '' || cur === badge) {
    return options.fn(this);
  }
  return options.inverse(this);
});

context.handlebars.registerHelper('hasVisibleIssues', function(data, options) {
  if (!data || !Array.isArray(data)) return options.inverse(this);
  const cur = context.grafana.replaceVariables('${severity}');
  const visible = data.filter(function(r) {
    if (!r || !r.Headline) return false;
    return !cur || cur === 'All' || cur === '.*' || cur === '' || cur === r.SeverityBadge;
  });
  if (visible.length > 0) {
    return options.fn(this);
  }
  return options.inverse(this);
});

context.handlebars.registerHelper('currentSeverity', function() {
  const cur = context.grafana.replaceVariables('${severity}');
  return (!cur || cur === '.*') ? 'All' : cur;
});

context.handlebars.registerHelper('urlTimeRange', function() {
  return context.grafana.replaceVariables('${__url_time_range}') || 'from=now-5m&to=now';
});

context.handlebars.registerHelper('formatIssueValue', function(row) {
  if (!row) return '0';
  const headline = (row.Headline || '').toLowerCase();
  const metricType = (row.MetricType || '').toLowerCase();

  // 1. Repeated Queries (N+1 anomaly) -> show impacted requests count
  if (headline.includes('repeated') || metricType.includes('repeated') || row.refId === 'H') {
    const val = row['Value #H'] !== undefined ? row['Value #H'] : (row.Value !== undefined ? row.Value : 0);
    const num = Math.round(Number(val) || 0);
    return num + ' requests';
  }

  // 2. Latency anomalies
  if (headline.includes('latency') || metricType.includes('latency')) {
    let lat = null;
    if (row['Value #A'] !== undefined) lat = Number(row['Value #A']);
    else if (row['Value #B'] !== undefined) lat = Number(row['Value #B']);
    else if (row['Value #C'] !== undefined) lat = Number(row['Value #C']);
    else if (row.Value !== undefined) lat = Number(row.Value);
    if (lat !== null) return 'P95 ' + lat.toFixed(1) + ' ms';
  }

  // 3. Error rates
  if (headline.includes('error') || headline.includes('failure') || metricType.includes('error')) {
    let err = null;
    if (row['Value #D'] !== undefined) err = Number(row['Value #D']);
    else if (row['Value #E'] !== undefined) err = Number(row['Value #E']);
    else if (row['Value #F'] !== undefined) err = Number(row['Value #F']);
    else if (row.Value !== undefined) err = Number(row.Value);
    if (err !== null) return err.toFixed(1) + '%';
  }

  // 4. Traffic surge
  if (headline.includes('surge') || metricType.includes('rps')) {
    if (row['Value #G_curr'] !== undefined) {
      return Number(row['Value #G_curr']).toFixed(1) + ' req/s';
    }
    if (row['Value #G'] !== undefined) {
      return '+' + Number(row['Value #G']).toFixed(1) + '%';
    }
  }

  // Fallback
  if (row.Value !== undefined) {
    return Number(row.Value).toFixed(1) + (row.MetricUnit ? ' ' + row.MetricUnit : '');
  }
  return '-';
});

context.handlebars.registerHelper('formatIssueThreshold', function(row) {
  if (!row) return '-';
  const headline = (row.Headline || '').toLowerCase();
  const metricType = (row.MetricType || '').toLowerCase();

  if (headline.includes('repeated') || metricType.includes('repeated') || row.refId === 'H') {
    return 'Repeated query candidate';
  }

  if (headline.includes('latency') || metricType.includes('latency')) {
    let base = null;
    if (row['Value #A_base'] !== undefined) base = Number(row['Value #A_base']);
    else if (row['Value #B_base'] !== undefined) base = Number(row['Value #B_base']);
    else if (row['Value #C_base'] !== undefined) base = Number(row['Value #C_base']);
    if (base !== null && base > 0) return base.toFixed(1) + ' ms';
    return row.BaselineText || 'Median 30m';
  }

  if (headline.includes('error') || headline.includes('failure') || metricType.includes('error')) {
    if (row['Value #D'] !== undefined) return '> 2.0%';
    if (row['Value #E'] !== undefined) return '> 1.0%';
    if (row['Value #F'] !== undefined) return '> 1.0%';
    return '> 0.0%';
  }

  if (headline.includes('surge') || metricType.includes('rps')) {
    if (row['Value #G_base'] !== undefined) {
      return Number(row['Value #G_base']).toFixed(1) + ' req/s';
    }
    return row.BaselineText || '1h Median';
  }

  return row.BaselineText || '-';
});

context.handlebars.registerHelper('formatIssueStatus', function(row) {
  if (!row) return 'Active';
  const headline = (row.Headline || '').toLowerCase();
  const metricType = (row.MetricType || '').toLowerCase();

  if (headline.includes('repeated') || metricType.includes('repeated') || row.refId === 'H') {
    return 'Repeated';
  }
  if (headline.includes('error') || headline.includes('failure') || metricType.includes('error')) {
    return 'Critical';
  }
  if (row.Deviation) {
    return row.Deviation;
  }
  return 'Elevated';
});

options.afterRender:
const selSev = context.grafana.replaceVariables('${severity}');
const el = context.element;
if (el) {
  const oldOverlay = document.getElementById('dd-drawer-overlay');
  if (oldOverlay) oldOverlay.remove();

  const rows = el.querySelectorAll('tbody tr.tn-row');
  rows.forEach(function(r) {
    const badge = r.getAttribute('data-severity');
    if (!selSev || selSev === 'All' || selSev === '.*' || selSev === '' || selSev === badge) {
      r.style.setProperty('display', '', 'important');
    } else {
      r.style.setProperty('display', 'none', 'important');
    }
  });
}

